-- =====================================================================
-- GapFinder - seed data
-- Spring runs it on startup (spring.sql.init.mode=always).
-- It runs ONLY once: it first checks whether the demo account
-- laura.gomez@uniandes.edu.co with the seed hash exists. If it does, nothing is inserted.
-- Dates are relative to the week it is loaded (Monday 00:00 =
-- date_trunc('week', LOCALTIMESTAMP)).
-- Password of every user: Gapfinder123
-- =====================================================================
DROP TABLE IF EXISTS pg_temp.seed_run;
CREATE TEMP TABLE seed_run AS SELECT NOT EXISTS (SELECT 1 FROM users WHERE email = 'laura.gomez@uniandes.edu.co' AND password_hash = '$2a$10$SkID9TwSPunoci1Ru0/Dj.oXIEnTVH7JsXv4Y9W1HslZogKZgVgP.') AS go;
CREATE TEMP TABLE IF NOT EXISTS seed_friendships (id bigint);
CREATE TEMP TABLE IF NOT EXISTS seed_matches (id bigint);
CREATE TEMP TABLE IF NOT EXISTS seed_participants (id bigint);
TRUNCATE seed_friendships, seed_matches, seed_participants;
-- ---------- interests
INSERT INTO interests (name)
SELECT v.name
FROM (VALUES
('Soccer'),
('Basketball'),
('Volleyball'),
('Running'),
('Cycling'),
('Yoga'),
('Gym'),
('Swimming'),
('Chess'),
('Video games'),
('Board games'),
('Music'),
('Dance'),
('Movies'),
('Reading'),
('Creative writing'),
('Photography'),
('Painting'),
('Programming'),
('Entrepreneurship'),
('Languages'),
('Environment'),
('Debate'),
('Cooking'),
('Studying')
) AS v(name)

WHERE (SELECT go FROM seed_run)
AND NOT EXISTS (SELECT 1 FROM interests x WHERE x.name = v.name);
-- ---------- buildings (coordinates from Lats_Long.xlsx, point = ST_MakePoint(longitude, latitude))
INSERT INTO buildings (name, location, radius_meters)
SELECT v.name, ST_SetSRID(ST_MakePoint(v.lng::float8, v.lat::float8), 4326)::geography, v.r::float8
FROM (VALUES
('SD', 4.60453173138371, -74.0657957137293, 28.3),
('ML', 4.60277854608654, -74.0648662947269, 37.4),
('RGD (Cívico) 1', 4.60259053382499, -74.0658763428045, 15.5),
('RGD (Cívico) 2', 4.60237951907638, -74.0659499766761, 16.2),
('Aulas 1', 4.60266145931342, -74.0662938348606, 19.8),
('Aulas 2', 4.60272458404028, -74.0666015355127, 20.1),
('Bobo 1', 4.60122604850284, -74.0658814905777, 16.4),
('Bobo 2', 4.6011739139905, -74.065599188094, 18.6),
('C', 4.60130759222048, -74.065088227267, 25.5),
('Cafetería', 4.60076131229269, -74.0652130142143, 12.3),
('TX', 4.60121238581797, -74.0638128225318, 20.1),
('City U', 4.60332616587851, -74.0669914949544, 36.3),
('Caneca', 4.60033983903569, -74.0629191002404, 80.7)
) AS v(name, lat, lng, r)

WHERE (SELECT go FROM seed_run)
AND NOT EXISTS (SELECT 1 FROM buildings x WHERE x.name = v.name);
